
.sh {
  padding: 8px 10px;
  margin-bottom: 8px;
}

.sh__bar {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.sh__scene {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 2px 16px;
}

.sh__edit {
  flex: 0 0 auto;
  border: 1px solid var(--hud-border);
  background: transparent;
  color: var(--hud-mute);
  border-radius: 2px;
  padding: 1px 8px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;

  &:hover {
    background: var(--theme-soft);
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }
}

.sh__rel {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 16px;
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid var(--hud-rule);
}

.sh__reached {
  font-size: 11px;
  color: var(--hud-mute);
}

.sh__affection {
  flex: 1 1 160px;
  min-width: 140px;
}

.sh__actions {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}

.sh__btn {
  border: 1px solid var(--hud-border);
  background: transparent;
  color: var(--hud-text);
  border-radius: 2px;
  padding: 2px 12px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;

  &:hover {
    background: var(--theme-soft);
  }
}

.sh__btn--primary {
  border-color: var(--theme-primary);
  color: var(--theme-accent);
  font-weight: 700;
}
