
.tk__block {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--hud-rule);

  &:first-of-type {
    margin-top: 0;
    padding-top: 0;
    border-top: none;
  }
}

.tk__h {
  font-size: 12px;
  font-weight: 700;
  color: var(--hud-mute);
  margin-bottom: 4px;

  i {
    margin-right: 4px;
  }
}

.tk__note {
  font-weight: 400;
  font-size: 11px;
}

.tk__slots,
.tk__lib {
  list-style: none;
}

.tk__slot,
.tk__row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 8px;
  padding: 3px 0;
  border-bottom: 1px dashed var(--hud-rule);

  &:last-child {
    border-bottom: none;
  }
}

.tk__slot-key {
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--hud-mute);
}

.tk__row--off {
  opacity: 0.62;
}

.tk__own {
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--hud-mute);
  cursor: pointer;
  user-select: none;

  input {
    margin-right: 3px;
    vertical-align: -1px;
  }
}

.tk__own-flag {
  flex: 0 0 auto;
  font-size: 11px;
}

.tk__own-flag--yes {
  color: var(--c-success);
}
.tk__own-flag--no {
  color: var(--hud-mute);
}

.tk__equipped {
  flex: 0 0 auto;
  font-size: 11px;
  color: var(--theme-accent);
  border: 1px solid currentcolor;
  border-radius: 2px;
  padding: 0 4px;
  line-height: 1.4;
}

.tk__del {
  flex: 0 0 auto;
  margin-left: auto;
  border: none;
  background: transparent;
  color: var(--hud-mute);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  padding: 0 2px;

  &:hover {
    color: var(--c-danger);
  }
}

.tk__empty,
.tk__bench,
.tk__hint {
  font-size: 11px;
  color: var(--hud-mute);
}

.tk__bench {
  margin-top: 4px;
}

.tk__warn {
  margin-top: 4px;
  font-size: 11px;
  color: var(--c-warning);

  i {
    margin-right: 3px;
  }
}

.tk__add {
  display: flex;
  gap: 6px;
  margin-top: 6px;
}

.tk__add-input {
  flex: 1 1 auto;
  min-width: 0;
  font: inherit;
  color: var(--hud-text);
  background: var(--hud-bg-1);
  border: 1px solid var(--hud-border);
  border-radius: 2px;
  padding: 1px 6px;

  &:focus {
    outline: none;
    border-color: var(--theme-primary);
    box-shadow: 0 0 0 2px var(--theme-soft);
  }
}

.tk__add-btn {
  flex: 0 0 auto;
  border: 1px solid var(--hud-border);
  background: transparent;
  color: var(--hud-mute);
  border-radius: 2px;
  padding: 1px 8px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;

  &:disabled {
    opacity: 0.5;
    cursor: default;
  }

  &:not(:disabled):hover {
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }
}
