
.ef {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 24px;
  min-width: 0;
  flex-wrap: wrap;
}

.ef--block {
  flex-direction: column;
  align-items: stretch;
  gap: 3px;
}

.ef__label {
  font-size: 12px;
  color: var(--hud-mute);
  white-space: nowrap;
  flex: 0 0 auto;

  i {
    margin-right: 3px;
  }
}

.ef__value {
  flex: 1 1 auto;
  min-width: 0;
  word-break: break-word;
}

.ef__control {
  flex: 1 1 auto;
  min-width: 0;
  font: inherit;
  color: var(--hud-text);
  background: var(--hud-bg-1);
  border: 1px solid var(--hud-border);
  border-radius: 2px;
  padding: 1px 6px;

  &:focus {
    outline: none;
    border-color: var(--theme-primary);
    box-shadow: 0 0 0 2px var(--theme-soft);
  }
}

.ef__control--area {
  resize: vertical;
  line-height: 1.5;
  padding: 4px 6px;
}

.ef__hint {
  flex: 1 0 100%;
  font-size: 11px;
  color: var(--hud-mute);
}
