
/* 邀请态是常态纸面上的一张「递过来的条子」：主色压边 + 轻微抬起，
   但不用战斗态的暗底，因为这时还没开战。 */
.ip {
  padding: 8px 10px;
  background: var(--hud-bg-2);
  border: 1px solid var(--theme-primary);
  border-radius: 3px;
  box-shadow: 0 1px 0 var(--theme-soft);
}

.ip__title {
  font-size: 13px;
  font-weight: 700;
  color: var(--theme-accent);

  i {
    margin-right: 5px;
  }
}

.ip__lead {
  margin-top: 4px;
  font-size: 12px;
  line-height: 1.6;

  b {
    color: var(--theme-accent);
  }
}

.ip__stakes {
  margin-top: 6px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.ip__stake {
  display: flex;
  gap: 6px;
  font-size: 12px;
  line-height: 1.5;

  dt {
    flex: 0 0 auto;
    font-weight: 700;
    color: var(--c-success);
    white-space: nowrap;
  }

  dd {
    color: var(--hud-mute);
  }

  i {
    margin-right: 3px;
  }
}

.ip__stake--bad dt {
  color: var(--c-danger);
}

.ip__preview {
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid var(--hud-rule);
}

.ip__row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;

  dt {
    color: var(--hud-mute);
  }
}

.ip__warn {
  margin-top: 6px;
  font-size: 11px;
  line-height: 1.5;
  color: var(--c-warning);

  i {
    margin-right: 3px;
  }
}

.ip__actions {
  margin-top: 8px;
  display: flex;
  gap: 8px;
}

.ip__btn {
  flex: 1 1 0;
  padding: 5px 0;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  color: var(--hud-text);
  background: var(--hud-bg-1);
  border: 1px solid var(--hud-border);
  border-radius: 2px;
  cursor: pointer;

  &:hover {
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }

  i {
    margin-right: 4px;
  }
}

.ip__btn--accept {
  color: var(--hud-bg-1);
  background: var(--theme-primary);
  border-color: var(--theme-primary);

  &:hover {
    color: var(--hud-bg-1);
    background: var(--theme-accent);
    border-color: var(--theme-accent);
  }
}

.ip__note {
  margin-top: 6px;
  font-size: 11px;
  line-height: 1.6;
  color: var(--hud-mute);
}
