
.sc {
  margin-top: 5px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 1px 7px;
  font-size: 11px;
  border: 1px solid currentcolor;
  border-radius: 10px;
  cursor: help;
}

/* 权重三档用功能色分层，不另立调色：轻＝弱化字、中＝状态异常色、重＝危险色。 */
.sc--轻 {
  color: var(--hud-mute);
}
.sc--中 {
  color: var(--c-warning);
}
.sc--重 {
  color: var(--c-danger);
}

.sc__name {
  font-weight: 700;
}

.sc__rounds {
  color: var(--hud-mute);
}
