
.cb {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--hud-rule);
}

.cb__head {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.cb__face {
  flex: 0 0 44px;
  width: 44px;
}

.cb__meta {
  flex: 1 1 auto;
  min-width: 0;
}

.cb__meta-line {
  font-size: 12px;

  i {
    margin-right: 4px;
    color: var(--c-warning);
  }
}

.cb__meta-line--dim {
  margin-top: 2px;
  font-size: 11px;
  color: var(--hud-mute);
}

.cb__note {
  margin-top: 6px;
  font-size: 11px;
  line-height: 1.5;

  i {
    margin-right: 3px;
  }
}

.cb__note--warn {
  color: var(--c-warning);
}

.cb__note--err {
  color: var(--c-danger);
}

.cb__skills {
  margin-top: 6px;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.cb__skill,
.cb__item {
  display: block;
  width: 100%;
  text-align: left;
  font: inherit;
  color: var(--hud-text);
  background: var(--hud-bg-2);
  border: 1px solid var(--hud-border);
  border-radius: 2px;
  padding: 4px 6px;
  cursor: pointer;

  &:hover:not(:disabled) {
    border-color: var(--theme-primary);
    background: var(--theme-soft);
  }

  /* 置灰要一眼看出「不是我没点中，是它不给点」，所以降透明度＋换指针，边框同时收暗 */
  &:disabled {
    cursor: not-allowed;
    opacity: 0.5;
    border-style: dashed;
  }
}

/* 置灰原因必须显示，不能只放 title：手机上没有悬停（§11.3「并给出置灰原因」） */
.cb__why {
  display: block;
  margin-top: 2px;
  font-size: 11px;
  color: var(--c-warning);
}

.cb__bagtoggle {
  margin-top: 6px;
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  font: inherit;
  font-size: 12px;
  color: var(--hud-text);
  background: transparent;
  border: 1px solid var(--hud-border);
  border-radius: 2px;
  padding: 3px 6px;
  cursor: pointer;

  &:hover {
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }
}

.cb__bagcount {
  flex: 1 1 auto;
  text-align: right;
  font-size: 11px;
  color: var(--hud-mute);
}

.cb__bag {
  margin-top: 4px;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.cb__item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 8px;
}

.cb__item-empty {
  font-size: 12px;
  color: var(--hud-mute);
}

.cb__item-name {
  font-weight: 700;
}

.cb__item-tier {
  font-size: 11px;
  color: var(--hud-mute);
  border: 1px solid currentcolor;
  border-radius: 2px;
  padding: 0 4px;
  line-height: 1.4;
}

.cb__item-count {
  font-size: 12px;
  color: var(--hud-mute);
}

.cb__item-effect {
  flex: 1 1 100%;
  font-size: 11px;
  color: var(--hud-mute);
}

.cb__btn {
  font: inherit;
  font-size: 12px;
  color: var(--hud-text);
  background: var(--hud-bg-1);
  border: 1px solid var(--hud-border);
  border-radius: 2px;
  padding: 3px 10px;
  cursor: pointer;

  &:hover:not(:disabled) {
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }

  &:disabled {
    cursor: not-allowed;
    opacity: 0.5;
  }

  i {
    margin-right: 4px;
  }
}

/* 认输单独一格（§11.3），且与四招之间留出空隙——它不该看起来像第五个选项 */
.cb__btn--give {
  margin-top: 8px;
  width: 100%;
  color: var(--hud-mute);

  &:hover:not(:disabled) {
    border-color: var(--c-danger);
    color: var(--c-danger);
  }
}

.cb__btn--primary {
  border-color: var(--theme-primary);
  color: var(--theme-accent);
  font-weight: 700;
}

.cb__over {
  margin-top: 8px;
  padding: 8px;
  background: var(--hud-bg-2);
  border: 1px solid var(--theme-primary);
  border-radius: 3px;
  text-align: center;
}

.cb__over-text {
  font-size: 13px;
  margin-bottom: 6px;

  i {
    margin-right: 4px;
    color: var(--theme-accent);
  }
}

.cb__confirm {
  margin-top: 8px;
  padding: 6px 8px;
  background: var(--hud-bg-2);
  border: 1px solid var(--theme-primary);
  border-radius: 2px;
}

.cb__confirm-text {
  font-size: 12px;

  b {
    color: var(--theme-accent);
  }
}

.cb__confirm-row {
  margin-top: 5px;
  display: flex;
  gap: 8px;
}

.cb__inner {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid var(--hud-rule);
}

.cb__inner-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  color: var(--hud-mute);

  i {
    margin-right: 4px;
  }
}

.cb__toggle {
  border: none;
  background: transparent;
  color: var(--theme-accent);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
  padding: 0;
}

.cb__inner-text {
  margin-top: 3px;
  font-size: 12px;
  line-height: 1.6;
}

/* 遮住而不是留空：她那句话照排，只加一层模糊——空占位符会让人以为她没想什么 */
.cb__inner-text--veiled {
  filter: blur(4px);
  cursor: pointer;
  user-select: none;
}

.cb__foot {
  margin-top: 10px;
  padding-top: 6px;
  border-top: 1px solid var(--hud-rule);
  display: flex;
  gap: 8px;
}

.cb__foot-btn {
  flex: 1 1 0;
  font: inherit;
  font-size: 11px;
  color: var(--hud-mute);
  background: transparent;
  border: 1px solid var(--hud-border);
  border-radius: 2px;
  padding: 2px 0;
  cursor: pointer;

  &:hover {
    border-color: var(--theme-primary);
    color: var(--theme-accent);
  }

  i {
    margin-right: 3px;
  }
}
